mapper.select:
select   
order by h.occurred_at desc, h.insp_id desc
limit #{limit}

select 
  from qms_insp h join lot_master l on l.lot_id = h.lot_id
 where h.item_id = #{itemId}

       and h.proc_id = #{procId}
       and h.proc_id is null

   and h.insp_type in ('FIRST_OFF', 'LAST_OFF') and h.status <> 'VOID'
 order by h.occurred_at desc, h.insp_id desc
 limit #{limit}

select l.lot_id, l.item_id, i.item_class_id, l.qty_created, l.unit_cd = i.unit_cd as base_unit
  from lot_master l join mst_item i on i.item_id = l.item_id
 where l.lot_no = #{lotNo}

mapper.update:
update qms_insp set status = 'JUDGED', result = #{result}, judged_at = now(), judged_by = #{by}, judged_worker_id = #{workerId,jdbcType=BIGINT},
                    row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{id} and status = 'OPEN' and row_ver = #{rowVer}

update qms_insp set status = 'VOID', void_reason = #{reason}, voided_at = now(), voided_by = #{by},
                    row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where insp_id = #{id} and status in ('OPEN', 'JUDGED') and row_ver = #{rowVer}
